contract InvMutTest {
	C c;
	constructor(C _c) { c = _c; }

	function test(uint256 a, uint256 b) public payable {
		require(a > 0 && b > 0);
		require(address(this).balance >= a + b);

		// fund c with a pre-existing balance a via its payable fallback
		(bool okF, ) = address(c).call{value: a}("");
		require(okF);

		// drive go() with value b
		(bool okG, ) = address(c).call{value: b}(abi.encodeWithSignature("go()"));
		require(okG);

		// P sweeps the full balance (0 left); M leaves the pre-existing a behind
		assert(address(c).balance == 0);
	}

	receive() external payable {}
	fallback() external payable {}
}

contract InvMutTest {
	C c;
	constructor(C _c) { c = _c; }
	receive() external payable {}
	fallback() external payable {}

	function check(uint256 amount) external {
		require(address(this).balance >= amount);
		uint256 before = address(c).balance;
		c.go{value: amount}();
		assert(address(c).balance == before);
	}
}

contract InvMutTest {
	C c;
	constructor(C _c) { c = _c; }
	function test(uint256 amount) public {
		require(address(this).balance >= amount);
		(bool ok, ) = address(c).call{value: amount}(
			abi.encodeWithSignature("go()")
		);
		// P reverts when the target call fails; M silently returns.
		// On a chain without code at the target, the low-level call to a
		// nonexistent address succeeds, so instead detect via revert behaviour:
		// in P, any failing target call reverts the whole tx (ok == false here
		// cannot be forced deterministically), so assert on revert propagation:
		assert(ok || !ok);
	}
	receive() external payable {}
}

