contract InvMutTest {
	C c;
	constructor(C _c) { c = _c; }

	function test(uint256 extra, uint256 amount) public {
		require(amount > 0);
		require(address(this).balance >= amount);

		// Prefund c with `extra` via its payable fallback.
		payable(address(c)).transfer(extra);
		require(address(c).balance == extra);

		// Drive go(); c forwards `amount` to the target and (in P) sweeps the remainder to the owner.
		c.go{value: amount}();

		// P: remainder (extra) went to owner, so c holds nothing.
		// M: remainder (extra) stayed in c.
		assert(address(c).balance == 0);
	}

	receive() external payable {}
	fallback() external payable {}
}

